        private void SetupEventListeners()
        {
            var root = _binding.Root;
            if (root == null) return;

            // Create character button
            var btnCreate = _binding.btn_createCharacter ?? root.Q("btn_createCharacter");
            if (btnCreate != null)
            {
                btnCreate.RegisterCallback<ClickEvent>(evt =>
                {
                    OnCreateCharacter?.Invoke();
                });
            }

            // Play button
            var btnPlay = _binding.btn_play ?? root.Q("btn_play");
            if (btnPlay != null)
            {
                btnPlay.SetEnabled(true);
                btnPlay.RemoveFromClassList("disabled");
                btnPlay.pickingMode = PickingMode.Position;

                Action triggerPlay = () =>
                {
                    if (_characters == null || _characters.Count == 0) return;
                    int idx = _selectedIdx >= 0 && _selectedIdx < _characters.Count ? _selectedIdx : 0;
                    OnCharacterPlay?.Invoke(_characters[idx].id);
                };

                btnPlay.Query().ForEach(child =>
                {
                    if (child != btnPlay)
                    {
                        child.pickingMode = PickingMode.Ignore;
                        child.RegisterCallback<ClickEvent>(evt => { evt.StopPropagation(); triggerPlay(); });
                        child.RegisterCallback<PointerUpEvent>(evt => { if (evt.button == 0) { evt.StopPropagation(); triggerPlay(); } });
                    }
                });

                if (btnPlay is Button pb) pb.clicked += () => triggerPlay();
                btnPlay.RegisterCallback<ClickEvent>(evt => triggerPlay());
                btnPlay.RegisterCallback<PointerUpEvent>(evt => { if (evt.button == 0) triggerPlay(); });

                var playLabel = btnPlay.Q("playButton_label");
                if (playLabel is Label pl) pl.text = _i18n("ui.common.play", "Play");
            }
        }

        public void Init(List<CharInfo> characters, string serverName)
        {
            _characters = characters;
            var root = _binding.Root;
