            // Server name (from decompiled CharacterSelection.Localize: lbl_serverName = server name)
            var lblServer = root.Q<Label>("lbl_serverName");
            if (lblServer != null)
            {
                lblServer.text = !string.IsNullOrEmpty(serverName) ? serverName : "";
            }

            if (_characters == null || _characters.Count == 0)
            {
                var btnCreate = _binding.btn_createCharacter ?? root.Q("btn_createCharacter");
                if (btnCreate != null)
                {
                    btnCreate.style.display = DisplayStyle.Flex;
                }
                var btnPlay = _binding.btn_play ?? root.Q("btn_play");
                if (btnPlay != null)
                {
                    btnPlay.style.display = DisplayStyle.None;
                }
                return;
            }

            FillCharacters(_characters);
        }

        private void FillCharacters(List<CharInfo> characters)
        {
            var root = _binding.Root;
            var scrollView = _binding.gd_character ?? root.Q("gd_character");
            if (scrollView == null) return;

            scrollView.Clear();
            _selectedIdx = -1;

            VisualTreeAsset charLineUxml = _uxmlLoader?.Invoke("characterline");

            for (int i = 0; i < characters.Count; i++)
            {
                var ch = characters[i];
                VisualElement row;

                if (charLineUxml != null)
                {
                    row = charLineUxml.CloneTree();
                    var nameLabel = row.Q<Label>("lbl_name");
                    if (nameLabel != null) nameLabel.text = ch.name;
                    var levelLabel = row.Q<Label>("lbl_level");
                    if (levelLabel != null) levelLabel.text = $"{ch.level}";
                }
                else
                {
                    row = new VisualElement();
                    var nameLabel = new Label(ch.name) { name = "lbl_name" };
                    nameLabel.AddToClassList("DofusLabel");
                    row.Add(nameLabel);

                    var levelLabel = new Label($"{ch.level}") { name = "lbl_level" };
                    levelLabel.AddToClassList("DofusLabel");
                    row.Add(levelLabel);
                }

                row.name = $"charRow_{i}";
                int charIdx = i;
                int charId = ch.id;
                row.RegisterCallback<ClickEvent>(evt =>
                {
                    SetSelection(charIdx);
                    OnCharacterSelected?.Invoke(charId);
                });

                scrollView.Add(row);
            }

            // Default selection: first character
            if (characters.Count > 0)
            {
                SetSelection(0);
            }
        }

        public void SetSelection(int index)
        {
            _selectedIdx = index;
            var root = _binding.Root;
            var scrollView = _binding.gd_character ?? root.Q("gd_character");
            if (scrollView == null) return;

            for (int i = 0; i < scrollView.childCount; i++)
            {
                var row = scrollView[i];
                if (i == index)
                {
                    row.AddToClassList("selected");
                }
                else
                {
                    row.RemoveFromClassList("selected");
                }
            }
        }
    }
